-- INACTIVE PROTOTYPE: not in drizzle/ and not applied to any hosted database.
CREATE TABLE release_admission (
 channel TEXT PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE, owner TEXT NOT NULL,
 epoch INTEGER NOT NULL CHECK(epoch>0), target_revision TEXT NOT NULL,
 target_digest TEXT NOT NULL, target_commit TEXT NOT NULL,
 expected_revision TEXT, expected_generation INTEGER NOT NULL CHECK(expected_generation>=0),
 mode TEXT NOT NULL CHECK(mode IN ('publish','rollback','bootstrap')),
 state TEXT NOT NULL CHECK(state IN ('preparing','admitted','consumed')),
 stopped INTEGER NOT NULL CHECK(stopped IN (0,1))
);
ALTER TABLE content_revisions ADD COLUMN writer_operation TEXT;
ALTER TABLE content_revisions ADD COLUMN writer_owner TEXT;
ALTER TABLE content_revisions ADD COLUMN writer_epoch INTEGER;
CREATE TRIGGER fence_content_revisions_delete BEFORE DELETE ON content_revisions BEGIN SELECT RAISE(ABORT,'fence-delete-forbidden'); END;
ALTER TABLE content_records ADD COLUMN writer_operation TEXT;
ALTER TABLE content_records ADD COLUMN writer_owner TEXT;
ALTER TABLE content_records ADD COLUMN writer_epoch INTEGER;
CREATE TRIGGER fence_content_records_delete BEFORE DELETE ON content_records BEGIN SELECT RAISE(ABORT,'fence-delete-forbidden'); END;
ALTER TABLE content_publication_provenance ADD COLUMN writer_operation TEXT;
ALTER TABLE content_publication_provenance ADD COLUMN writer_owner TEXT;
ALTER TABLE content_publication_provenance ADD COLUMN writer_epoch INTEGER;
CREATE TRIGGER fence_content_publication_provenance_delete BEFORE DELETE ON content_publication_provenance BEGIN SELECT RAISE(ABORT,'fence-delete-forbidden'); END;
ALTER TABLE content_publication_events ADD COLUMN writer_operation TEXT;
ALTER TABLE content_publication_events ADD COLUMN writer_owner TEXT;
ALTER TABLE content_publication_events ADD COLUMN writer_epoch INTEGER;
CREATE TRIGGER fence_content_publication_events_delete BEFORE DELETE ON content_publication_events BEGIN SELECT RAISE(ABORT,'fence-delete-forbidden'); END;
ALTER TABLE content_publication ADD COLUMN writer_operation TEXT;
ALTER TABLE content_publication ADD COLUMN writer_owner TEXT;
ALTER TABLE content_publication ADD COLUMN writer_epoch INTEGER;
CREATE TRIGGER fence_content_publication_delete BEFORE DELETE ON content_publication BEGIN SELECT RAISE(ABORT,'fence-delete-forbidden'); END;
CREATE TRIGGER fence_content_revisions_insert BEFORE INSERT ON content_revisions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a WHERE NEW.completed=0 AND a.operation_id=NEW.writer_operation AND a.owner=NEW.writer_owner AND a.epoch=NEW.writer_epoch AND a.stopped=0 AND a.state='preparing' AND a.target_revision=NEW.id AND a.target_digest=NEW.digest AND a.channel='engine:'||NEW.engine) THEN RAISE(ABORT,'fence-admission-rejected') END; END;
CREATE TRIGGER fence_content_revisions_update BEFORE UPDATE ON content_revisions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a WHERE a.operation_id=NEW.writer_operation AND a.owner=NEW.writer_owner AND a.epoch=NEW.writer_epoch AND a.stopped=0 AND a.state='preparing' AND a.target_revision=NEW.id AND a.target_digest=NEW.digest AND a.channel='engine:'||NEW.engine AND OLD.rowid=NEW.rowid AND OLD.id=NEW.id AND OLD.engine=NEW.engine AND OLD.schema_version=NEW.schema_version AND OLD.digest=NEW.digest AND OLD.manifest_json=NEW.manifest_json AND OLD.bundle_json=NEW.bundle_json AND OLD.record_count=NEW.record_count AND OLD.completed=0 AND NEW.completed=1) THEN RAISE(ABORT,'fence-admission-rejected') END; END;
CREATE TRIGGER fence_content_records_insert BEFORE INSERT ON content_records BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a WHERE a.operation_id=NEW.writer_operation AND a.owner=NEW.writer_owner AND a.epoch=NEW.writer_epoch AND a.stopped=0 AND a.state='preparing' AND a.target_revision=NEW.revision_id AND EXISTS(SELECT 1 FROM content_revisions r WHERE r.id=NEW.revision_id AND a.channel='engine:'||r.engine AND a.target_digest=r.digest AND r.completed=0)) THEN RAISE(ABORT,'fence-admission-rejected') END; END;
CREATE TRIGGER fence_content_records_update BEFORE UPDATE ON content_records BEGIN SELECT RAISE(ABORT,'fence-immutable'); END;
CREATE TRIGGER fence_content_publication_provenance_insert BEFORE INSERT ON content_publication_provenance BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a WHERE a.operation_id=NEW.writer_operation AND a.owner=NEW.writer_owner AND a.epoch=NEW.writer_epoch AND a.stopped=0 AND a.state='preparing' AND a.target_revision=NEW.revision_id AND a.target_commit=NEW.commit_sha AND NEW.repository='LeiterConsulting/splunk-version-value-explorer') THEN RAISE(ABORT,'fence-admission-rejected') END; END;
CREATE TRIGGER fence_content_publication_provenance_update BEFORE UPDATE ON content_publication_provenance BEGIN SELECT RAISE(ABORT,'fence-immutable'); END;
CREATE TRIGGER fence_content_publication_events_insert BEFORE INSERT ON content_publication_events BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a WHERE NEW.operation_id=NEW.writer_operation AND (a.mode='bootstrap' OR (NEW.from_revision!=NEW.to_revision AND ((a.mode='rollback' AND EXISTS(SELECT 1 FROM content_publication_events h WHERE h.channel=a.channel AND (h.from_revision=a.target_revision OR h.to_revision=a.target_revision))) OR (a.mode='publish' AND NOT EXISTS(SELECT 1 FROM content_publication_events h WHERE h.channel=a.channel AND (h.from_revision=a.target_revision OR h.to_revision=a.target_revision)))))) AND a.operation_id=NEW.writer_operation AND a.owner=NEW.writer_owner AND a.epoch=NEW.writer_epoch AND a.stopped=0 AND a.state='admitted' AND a.channel=NEW.channel AND a.target_revision=NEW.to_revision AND a.target_commit=NEW.provenance_commit AND NEW.generation=a.expected_generation+1 AND ((a.mode='bootstrap' AND a.expected_revision IS NULL AND a.expected_generation=0 AND NEW.from_revision=a.target_revision AND NEW.intent='publish' AND NOT EXISTS(SELECT 1 FROM content_publication p WHERE p.channel=a.channel)) OR (a.mode IN ('publish','rollback') AND NEW.intent=a.mode AND NEW.from_revision=a.expected_revision AND EXISTS(SELECT 1 FROM content_publication p WHERE p.channel=a.channel AND p.revision_id=a.expected_revision))) AND COALESCE((SELECT MAX(e.generation) FROM content_publication_events e WHERE e.channel=a.channel),0)=a.expected_generation AND EXISTS(SELECT 1 FROM content_revisions r JOIN content_publication_provenance pr ON pr.revision_id=r.id WHERE r.id=a.target_revision AND r.completed=1 AND r.digest=a.target_digest AND a.channel='engine:'||r.engine AND pr.commit_sha=a.target_commit)) THEN RAISE(ABORT,'fence-admission-rejected') END; END;
CREATE TRIGGER fence_content_publication_events_update BEFORE UPDATE ON content_publication_events BEGIN SELECT RAISE(ABORT,'fence-immutable'); END;
CREATE TRIGGER fence_content_publication_insert BEFORE INSERT ON content_publication BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a WHERE a.operation_id=NEW.writer_operation AND a.owner=NEW.writer_owner AND a.epoch=NEW.writer_epoch AND a.stopped=0 AND a.state='admitted' AND a.channel=NEW.channel AND a.target_revision=NEW.revision_id AND EXISTS(SELECT 1 FROM content_publication_events e WHERE e.operation_id=a.operation_id AND e.channel=a.channel AND e.to_revision=a.target_revision AND e.generation=a.expected_generation+1 AND e.writer_operation=a.operation_id AND e.writer_owner=a.owner AND e.writer_epoch=a.epoch) AND a.mode='bootstrap' AND a.expected_revision IS NULL) THEN RAISE(ABORT,'fence-admission-rejected') END; END;
CREATE TRIGGER fence_content_publication_update BEFORE UPDATE ON content_publication BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a WHERE a.operation_id=NEW.writer_operation AND a.owner=NEW.writer_owner AND a.epoch=NEW.writer_epoch AND a.stopped=0 AND a.state='admitted' AND a.channel=NEW.channel AND a.target_revision=NEW.revision_id AND EXISTS(SELECT 1 FROM content_publication_events e WHERE e.operation_id=a.operation_id AND e.channel=a.channel AND e.to_revision=a.target_revision AND e.generation=a.expected_generation+1 AND e.writer_operation=a.operation_id AND e.writer_owner=a.owner AND e.writer_epoch=a.epoch) AND a.mode IN ('publish','rollback') AND OLD.rowid=NEW.rowid AND OLD.channel=NEW.channel AND OLD.revision_id=a.expected_revision) THEN RAISE(ABORT,'fence-admission-rejected') END; END;
CREATE TRIGGER consume_content_publication_insert AFTER INSERT ON content_publication BEGIN UPDATE release_admission SET state='consumed' WHERE channel=NEW.channel AND operation_id=NEW.writer_operation AND owner=NEW.writer_owner AND epoch=NEW.writer_epoch AND stopped=0 AND state='admitted'; SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,'fence-consumption-failed') END; END;
CREATE TRIGGER consume_content_publication_update AFTER UPDATE ON content_publication BEGIN UPDATE release_admission SET state='consumed' WHERE channel=NEW.channel AND operation_id=NEW.writer_operation AND owner=NEW.writer_owner AND epoch=NEW.writer_epoch AND stopped=0 AND state='admitted'; SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,'fence-consumption-failed') END; END;
CREATE TRIGGER fence_content_revisions_no_replace BEFORE INSERT ON content_revisions BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM content_revisions x WHERE x.id=NEW.id) OR EXISTS(SELECT 1 FROM content_revisions x WHERE x.rowid=NEW.rowid) THEN RAISE(ABORT,'fence-existing-row') END; END;
CREATE TRIGGER fence_content_records_no_replace BEFORE INSERT ON content_records BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM content_records x WHERE x.revision_id=NEW.revision_id AND x.record_id=NEW.record_id) OR EXISTS(SELECT 1 FROM content_records x WHERE x.rowid=NEW.rowid) THEN RAISE(ABORT,'fence-existing-row') END; END;
CREATE TRIGGER fence_content_publication_provenance_no_replace BEFORE INSERT ON content_publication_provenance BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM content_publication_provenance x WHERE x.revision_id=NEW.revision_id) OR EXISTS(SELECT 1 FROM content_publication_provenance x WHERE x.rowid=NEW.rowid) THEN RAISE(ABORT,'fence-existing-row') END; END;
CREATE TRIGGER fence_content_publication_events_no_replace BEFORE INSERT ON content_publication_events BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM content_publication_events x WHERE x.operation_id=NEW.operation_id) OR EXISTS(SELECT 1 FROM content_publication_events x WHERE x.rowid=NEW.rowid) THEN RAISE(ABORT,'fence-existing-row') END; END;
CREATE TRIGGER fence_content_publication_no_replace BEFORE INSERT ON content_publication BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM content_publication x WHERE x.channel=NEW.channel) OR EXISTS(SELECT 1 FROM content_publication x WHERE x.rowid=NEW.rowid) THEN RAISE(ABORT,'fence-existing-row') END; END;
CREATE TRIGGER promote_admitted_event AFTER INSERT ON content_publication_events BEGIN
 INSERT INTO content_publication(channel,revision_id,writer_operation,writer_owner,writer_epoch)
 SELECT NEW.channel,NEW.to_revision,NEW.writer_operation,NEW.writer_owner,NEW.writer_epoch FROM release_admission a
 WHERE a.channel=NEW.channel AND a.operation_id=NEW.operation_id AND a.mode='bootstrap';
 UPDATE content_publication SET revision_id=NEW.to_revision,writer_operation=NEW.writer_operation,writer_owner=NEW.writer_owner,writer_epoch=NEW.writer_epoch
 WHERE channel=NEW.channel AND revision_id=NEW.from_revision AND EXISTS(SELECT 1 FROM release_admission a WHERE a.channel=NEW.channel AND a.operation_id=NEW.operation_id AND a.mode IN ('publish','rollback') AND a.state='admitted');
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a JOIN content_publication p ON p.channel=a.channel WHERE a.channel=NEW.channel AND a.operation_id=NEW.operation_id AND a.owner=NEW.writer_owner AND a.epoch=NEW.writer_epoch AND a.state='consumed' AND p.revision_id=NEW.to_revision) THEN RAISE(ABORT,'fence-promotion-incomplete') END;
END;
